import {FACTIONS,BUILDINGS,SECRETS,buildingCost,isNight} from '../content/living-world.js?v=0.8.0';
import {ENEMIES,ZONES,ITEM_TEMPLATES} from '../content/region.js?v=0.3.1';
import {createItem,derive,heal,addEffect,has,blocked,lineOfSight} from './rules.js?v=0.3.1';
import {salePrice} from '../content/economy.js?v=0.3.1';
import {trophySet} from './growth.js?v=0.7.0';
const dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
export const RECIPES={ward:{name:'Припаси дозору',out:'potion',count:3,materials:{herb:3,ore:2}},grove:{name:'Настій пралісу',out:'ether',count:3,materials:{herb:4,spore:2}},forge:{name:'Очищення жару',out:'embershard',count:2,materials:{ore:6,cavecrystal:1}}};
export function initLiving(h){h.reputation??={ward:0,grove:0,forge:0};h.patron??=null;h.homestead??={garden:0,workshop:0,hall:0,nextHarvest:0,trophies:[]};h.secrets??={};h.runeProgress??={};h.huntTarget??=null;}
const reserved=(sim,id)=>sim.s.offers.some(o=>o.item===id&&o.status==='pending');
const near=(sim,h,id)=>ZONES[sim.s.zone].objects.some(o=>o.id===id&&dist(h,o)<3&&lineOfSight(sim.s.zone,h,o,sim.s.flags));
function safe(sim,h){if(h.dead||h.cast||sim.s.enemies.some(e=>!e.dead&&(e.aggroTarget===h.id||e.aggression==='aggressive'&&dist(e,h)<e.aggroRange)))throw Error('Спершу вийдіть із бою');}
function spend(sim,h,zeny,materials){if(h.zeny<zeny)throw Error('Бракує золота');const ids=[];for(const [template,count]of Object.entries(materials)){const items=h.inventory.filter(i=>i.template===template&&!i.favorite&&!reserved(sim,i.id));if(items.length<count)throw Error('Бракує вільних матеріалів: '+ITEM_TEMPLATES[template].name);ids.push(...items.slice(0,count).map(i=>i.id));}const used=new Set(ids);h.inventory=h.inventory.filter(i=>!used.has(i.id));h.zeny-=zeny;}
export function livingCommand(sim,h,i){
 if(!['favorite','sellSelected','huntTrack','patron','factionBuy','homeUpgrade','homeHarvest','homeCraft','homeTrophy','runePress','secretClaim'].includes(i.type))return null;initLiving(h);
 if(i.type==='favorite'){const item=h.inventory.find(a=>a.id===i.id&&a.owner===h.id);if(!item||reserved(sim,item.id))throw Error('Предмет недоступний');item.favorite=!item.favorite;return{};}
 if(i.type==='huntTrack'){if(i.enemy===null){h.huntTarget=null;h.navigationMode='quest';return{};}if(!Object.hasOwn(ENEMIES,i.enemy)||!h.bestiary?.[i.enemy]?.kills)throw Error('Спершу відкрийте запис у бестіарії');if(i.template&&!trophySet(h,i.enemy)?.[1].pieces.includes(i.template))throw Error('Ця нагорода недоступна');h.huntTarget={enemy:i.enemy,template:i.template||null};h.navigationMode='hunt';return{};}
 if(i.type==='sellSelected'){if(!Array.isArray(i.ids)||i.ids.length<1||i.ids.length>200||new Set(i.ids).size!==i.ids.length)throw Error('Оберіть від 1 до 200 різних предметів');const items=i.ids.map(id=>h.inventory.find(a=>a.id===id&&a.owner===h.id));if(items.some(a=>!a||a.favorite||Object.values(h.equipment).includes(a.id)||reserved(sim,a.id)||salePrice(ITEM_TEMPLATES[a.template],a)<=0))throw Error('Серед вибраного є захищена або недоступна річ');const total=items.reduce((sum,a)=>sum+salePrice(ITEM_TEMPLATES[a.template],a),0),ids=new Set(i.ids);h.inventory=h.inventory.filter(a=>!ids.has(a.id));h.zeny+=total;sim.event('trade',{actor:h.id,text:'Продано '+items.length+' речей · +'+total+' Z'});return{sold:items.length,zeny:total};}
 safe(sim,h);
 if(i.type==='patron'||i.type==='factionBuy'){const f=FACTIONS[i.faction];if(!Object.hasOwn(FACTIONS,i.faction)||!near(sim,h,f.npc))throw Error('Поговоріть із представником фракції');if(i.type==='patron'){if(h.reputation[i.faction]<250||h.level<20)throw Error('Потрібні 250 довіри та рівень 20');if(h.patron===i.faction)throw Error('Це вже ваш покровитель');const cost=h.patron?5:0;if(h.echoes<cost)throw Error('Зміна покровителя: 5 відлунь');h.echoes-=cost;h.patron=i.faction;const d=derive(h);h.hp=Math.min(h.hp,d.hp);h.sp=Math.min(h.sp,d.sp);return{};}const tier=i.tier;if(!Number.isInteger(tier)||tier<1||tier>3||h.reputation[i.faction]<[100,250,500][tier-1]||h.level<tier*10)throw Error('Потрібен відповідний ранг і рівень');spend(sim,h,1000*tier,{});h.inventory.push(createItem('faction-'+i.faction+'-'+tier,h.id));return{};}
 if(i.type.startsWith('home')){if(!near(sim,h,'homestead'))throw Error('Поверніться до садиби у Вербовій слободі');const home=h.homestead;
 if(i.type==='homeUpgrade'){if(!Object.hasOwn(BUILDINGS,i.building)||home[i.building]>=3)throw Error('Будівля вже завершена або невідома');const cost=buildingCost(i.building,home[i.building]);spend(sim,h,cost.zeny,{[cost.material]:cost.count});home[i.building]++;if(i.building==='garden'&&home.garden===1)home.nextHarvest=sim.s.clock+300;return{};}
 if(i.type==='homeHarvest'){if(!home.garden||sim.s.clock<home.nextHarvest)throw Error('Травник ще вирощує новий урожай');home.nextHarvest=sim.s.clock+300;for(let n=0;n<home.garden*3;n++)h.inventory.push(createItem('herb',h.id));h.inventory.push(createItem('potion',h.id));return{};}
 if(i.type==='homeCraft'){if(!Object.hasOwn(RECIPES,i.faction)||home.workshop<1||h.reputation[i.faction]<250)throw Error('Потрібні майстерня та довіра фракції 250');const r=RECIPES[i.faction],materials=Object.fromEntries(Object.entries(r.materials).map(([k,n])=>[k,Math.max(1,Math.ceil(n/home.workshop))]));spend(sim,h,200,materials);for(let n=0;n<r.count;n++)h.inventory.push(createItem(r.out,h.id));return{};}
 if(i.type==='homeTrophy'){if(!ENEMIES[i.enemy]?.boss||!h.bestiary?.[i.enemy]?.kills)throw Error('Спершу переможіть цього боса');if(home.trophies.includes(i.enemy))home.trophies=home.trophies.filter(id=>id!==i.enemy);else{if(home.trophies.length>=home.hall)throw Error('Немає вільного постаменту');home.trophies.push(i.enemy);}h.hp=Math.min(h.hp,derive(h).hp);return{};}}
 if(i.type==='runePress'){const d=SECRETS[i.id];if(!Object.hasOwn(SECRETS,i.id)||!near(sim,h,i.id)||!Number.isInteger(i.rune)||i.rune<0||i.rune>2)throw Error('Підійдіть до рунічного каменя');if(h.secrets[i.id])throw Error('Таємницю вже розгадано');let n=h.runeProgress[i.id]||0;if(d.order[n]!==i.rune){h.runeProgress[i.id]=0;sim.event('story',{actor:h.id,text:'Камінь затих. Почніть послідовність спочатку.'});return{};}h.runeProgress[i.id]=n+1;if(n===2){h.secrets[i.id]=true;h.runeProgress[i.id]=0;if(i.id==='runes-crypt')sim.s.flags.secretChamber=true;else h.inventory.push(createItem(d.reward,h.id));sim.event('story',{actor:h.id,text:i.id==='runes-crypt'?'У північній стіні відкрився прохід.':'Руни згадали свою історію. Особиста нагорода у торбі.'});}return{};}
 if(i.type==='secretClaim'){if(!['secret-vault','night-spirit'].includes(i.id)||!near(sim,h,i.id))throw Error('Підійдіть до таємниці');if(h.secrets[i.id])throw Error('Нагороду вже отримано');if(i.id==='secret-vault'){if(!h.secrets['runes-crypt'])throw Error('Спершу розгадайте камінь у катакомбах');h.inventory.push(createItem('secret-bell',h.id));}else{if(!isNight(sim.s.clock))throw Error('Дух прокидається вночі: друга половина десятихвилинного циклу');h.echoes+=3;h.inventory.push(createItem('rune',h.id));}h.secrets[i.id]=true;sim.event('story',{actor:h.id,text:i.id==='night-spirit'?'Дух: «Не кожен загублений прагне дороги. Дехто чекає, щоб його згадали». +3 відлуння та руна.':'Скриня зберегла дзвін того, хто так і не повернувся. Особисту реліквію отримано.'});return{};}
 return{};
}
export function enemyTactics(sim,e,h,dt){if(e.boss||e.mechanicTarget)return false;const tactic=e.tactic||ENEMIES[e.type]?.tactic;if(e.cast?.kind==='mend'){e.cast.left-=dt;if(e.cast.left<=0){const ally=sim.s.enemies.find(a=>a.id===e.cast.target&&!a.dead&&!a.returning);if(ally&&dist(e,ally)<5&&lineOfSight(sim.s.zone,e,ally,sim.s.flags)){const value=heal(ally,ally.maxHp*.18);sim.event('heal',{actor:ally.id,value:Math.round(value)});}e.cast=null;}return true;}if(e.cast||has(e,'stun'))return false;if(tactic==='healer'&&sim.s.clock>=(e.supportAt||0)){const ally=sim.s.enemies.filter(a=>a!==e&&!a.dead&&!a.boss&&!a.returning&&!a.mechanicTarget&&a.hp<a.maxHp*.65&&dist(e,a)<5&&lineOfSight(sim.s.zone,e,a,sim.s.flags)).sort((a,b)=>a.hp/a.maxHp-b.hp/b.maxHp)[0];if(ally){e.supportAt=sim.s.clock+10;e.cast={kind:'mend',left:1.6,total:1.6,target:ally.id};e.action='cast';e.actionTime=1.6;sim.event('telegraph',{actor:e.id,text:e.name+' лікує союзника — перервіть підготовку!'});return true;}}
 if(tactic==='protector'&&sim.s.clock>=(e.supportAt||0)){const allies=sim.s.enemies.filter(a=>a!==e&&!a.dead&&!a.boss&&!a.returning&&!a.mechanicTarget&&dist(e,a)<3&&lineOfSight(sim.s.zone,e,a,sim.s.flags));if(allies.length){e.supportAt=sim.s.clock+8;for(const a of allies)addEffect(a,'guard',2.5,e.id);sim.event('buff',{actor:e.id,text:e.name+' прикриває союзників!'});}}
 if(tactic==='skirmisher'&&dist(e,h)>3&&dist(e,h)<8&&sim.s.clock>=(e.flankAt||0)&&!has(e,'root')){e.flankAt=sim.s.clock+6;const len=dist(e,h)||1;for(const sign of [1,-1]){const point={x:e.x+(h.y-e.y)/len*.8*sign,y:e.y-(h.x-e.x)/len*.8*sign};if(dist(point,e.home)<e.leash&&lineOfSight(sim.s.zone,e,point,sim.s.flags)&&!blocked(sim.s.zone,point.x,point.y,sim.s.flags)){e.x=point.x;e.y=point.y;e.action='walk';e.actionTime=.3;break;}}}return false;}
export function validateLiving(h){const integer=(n,max=1e9)=>Number.isSafeInteger(n)&&n>=0&&n<=max;if(h.reputation!==undefined&&(!h.reputation||Object.keys(h.reputation).sort().join()!=='forge,grove,ward'||Object.values(h.reputation).some(n=>!integer(n,10000))))throw Error('Невірна репутація');if(h.patron!=null&&(!Object.hasOwn(FACTIONS,h.patron)||(h.reputation?.[h.patron]||0)<250))throw Error('Невірний покровитель');if(h.homestead!==undefined){const a=h.homestead;if(!a||['garden','workshop','hall'].some(k=>!integer(a[k],3))||!Number.isFinite(a.nextHarvest)||a.nextHarvest<0||!Array.isArray(a.trophies)||a.trophies.length>a.hall||new Set(a.trophies).size!==a.trophies.length||a.trophies.some(id=>!ENEMIES[id]?.boss||!h.bestiary?.[id]?.kills))throw Error('Невірна садиба');}for(const [key,value]of Object.entries(h.secrets||{}))if(![...Object.keys(SECRETS),'secret-vault','night-spirit'].includes(key)||value!==true)throw Error('Невірні таємниці');for(const [key,value]of Object.entries(h.runeProgress||{}))if(!Object.hasOwn(SECRETS,key)||!integer(value,2))throw Error('Невірні руни');if(h.huntTarget!=null&&(!Object.hasOwn(ENEMIES,h.huntTarget.enemy)||!h.bestiary?.[h.huntTarget.enemy]?.kills||h.huntTarget.template&&!trophySet(h,h.huntTarget.enemy)?.[1].pieces.includes(h.huntTarget.template)))throw Error('Невірна ціль полювання');for(const it of [...h.inventory,...(h.storage||[])])if(it.favorite!==undefined&&typeof it.favorite!=='boolean')throw Error('Невірна позначка предмета');}
